// Native Rust benchmark using bounded-stdin CLI; never a browser/WASM claim.
// Called only with synthetic file generated by generate-synthetic.mjs.
import {spawnSync} from 'node:child_process';
import {mkdtempSync,rmSync,readFileSync,openSync,createReadStream} from 'node:fs';
import {createDeflateRaw} from 'node:zlib';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
const base=fileURLToPath(new URL('../',import.meta.url));
const [size='16',unit='mib',grid='1000',entropy='mixed']=process.argv.slice(2);
const work=mkdtempSync(join(tmpdir(),'ddv-rust-bench-'));
try{
 const input=join(work,'original.json'),output=join(work,'edited.json');
 const generate=spawnSync(process.execPath,[base+'/scripts/generate-synthetic.mjs',
  input,size,unit,grid,entropy],{encoding:'utf8',maxBuffer:1<<20});
 if(generate.status!==0)throw Error(generate.stderr);
 const fixture=JSON.parse(generate.stdout);
 let deflateBytes=0;
 const deflate=createReadStream(input).pipe(createDeflateRaw({level:6}));
 for await(const chunk of deflate)deflateBytes+=chunk.length;
 const exe=base+'/target/release/examples/patch_json';
 const time=spawnSync('/usr/bin/time',['-v',exe,
 '/World/RecurringEvents/0/ItemSpawning/NextOccurrence',
 '2126-08-20T00:00:00Z','2022-09-06T00:00:00Z','626'],{
  stdio:[openSync(input,'r'),openSync(output,'w'),'pipe'],encoding:'utf8',timeout:600000
 });
 if(time.status!==0)throw Error(time.stderr||String(time.error));
 const out=readFileSync(output);
 const before=readFileSync(input);
 const editedStr=out.toString('utf8');
 if(before.equals(out)||!editedStr.includes('"NextOccurrence":"2022-09-06T00:00:00Z"')||
    out.length!==before.length)throw Error('BAD_RUST_BENCH_RESULT');
 const js=spawnSync('/usr/bin/time',['-v',process.execPath,'--max-old-space-size=2048',
   base+'/scripts/js-full-tree-reference.mjs',input],{encoding:'utf8',
   maxBuffer:1024*1024,timeout:600000});
 const jsStats=js.status===0?JSON.parse(js.stdout.trim()):null;
 const jsRss=/Maximum resident set size \(kbytes\):\s*(\d+)/.exec(js.stderr);
 const jsElapsed=js.stderr.split('\n').find(line=>line.includes('Elapsed (wall clock) time'))
   ?.split('): ').at(-1)?.trim()||null;
 const match=/Maximum resident set size \(kbytes\):\s*(\d+)/.exec(time.stderr);
 const elapsedLine=time.stderr.split('\n').find(line=>line.includes('Elapsed (wall clock) time'));
 const wall=elapsedLine?.split('): ').at(-1)?.trim()||null;
 console.log(JSON.stringify({type:'RUST_NATIVE_SYNTHETIC_ONLY',
  fixtureBytes:fixture.bytes,fixtureMB:fixture.sizeMB,fixtureMiB:fixture.sizeMiB,
  gridObjects:fixture.gridObjects,entropy,
  deflateRawBytes:deflateBytes,deflateRatio:Number((deflateBytes/fixture.bytes).toFixed(6)),
  nativeObservedMaxRssKiB:match?Number(match[1]):null,
  jsFullTreeStatus:js.status===0?'PASS':'BLOCKED',
  jsFullTreeMaxRssKiB:jsRss?Number(jsRss[1]):null,
  jsFullTreeElapsed:jsElapsed,jsFullTree:jsStats,
  wallClock:wall,nativeExit:time.status,wasmBrowserMeasured:false,
  productP1gMeasured:false}));
} finally {rmSync(work,{recursive:true,force:true});}